// First WhatsApp to a new lead. Fixed template + variables (in production = a Meta-approved template).
// Primer WhatsApp a un lead nuevo. Plantilla fija + variables (en producción = plantilla aprobada por Meta).
const c = $input.first().json;
if (!c.found) return [];                       // lead no encontrado -> no se hace nada
const lead = c.lead;
if (lead.estado !== 'nuevo') return [];        // ya lo atendieron: nunca se le escribe dos veces la apertura

const n = c.negocio;
const es = lead.idioma === 'es';
const nombre = String(lead.nombre || '').trim().split(/\s+/)[0] || (es ? 'hola' : 'there');
const asistente = n.nombre_asistente || 'Sofía';
const spa = n.nombre || 'Lumière Aesthetics';
const s = c.servicio_interes;                  // null si eligió "No estoy segura"
const servicio = s ? (es ? s.nombre_es : s.nombre_en) : '';
const stop = es ? 'Responde STOP si no quieres recibir más mensajes.' : 'Reply STOP to opt out.';

let cuerpo;
if (es) {
  const intro = `Hola ${nombre} 👋 Soy ${asistente}, la asistente virtual de ${spa}.`;
  if (!s) cuerpo = `${intro} Recibí tu solicitud. ¿Qué te gustaría mejorar de tu piel o tu rostro? Te cuento qué tratamiento te puede servir y te ayudo a agendar tu consulta gratis por aquí mismo.`;
  else if (c.es_clienta_nueva) cuerpo = `${intro} Vi tu interés en *${servicio}*. Tu primera visita es una consulta gratis con análisis de piel, y te llevas $50 de crédito para tu primer tratamiento. ¿Qué día y a qué hora te queda bien? Te la agendo por aquí mismo.`;
  else cuerpo = `${intro} Qué bueno saber de ti otra vez. Vi tu interés en *${servicio}*. ¿Qué día y a qué hora te queda bien? Te agendo la cita por aquí mismo.`;
} else {
  const intro = `Hi ${nombre} 👋 I'm ${asistente}, the virtual assistant at ${spa}.`;
  if (!s) cuerpo = `${intro} I got your request. What would you like to improve about your skin or face? I'll tell you which treatment could fit and book your free consultation right here.`;
  else if (c.es_clienta_nueva) cuerpo = `${intro} I saw you're interested in *${servicio}*. Your first visit is a free consultation with a skin analysis, plus a $50 credit toward your first treatment. What day and time work for you? I can book it right here.`;
  else cuerpo = `${intro} Great to hear from you again. I saw you're interested in *${servicio}*. What day and time work for you? I can book it right here.`;
}

// Exactly the inputs of "P31 - Lumière Send WhatsApp" / Exactamente lo que recibe Send WhatsApp
return [{ json: {
  lead_id: lead.lead_id,
  whatsapp: lead.whatsapp,
  mensaje: `${cuerpo}\n\n${stop}`,
  origen: 'P31',
  rol: 'assistant'
} }];
